import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "./tests/utils";
import { ButtonLink } from "./ButtonLink";

describe("ButtonLink (SWI-1198)", () => {
  describe("external URLs", () => {
    it("renders a plain anchor for http URLs", () => {
      renderWithProviders(
        <ButtonLink to="https://example.com" target="_blank">
          Visit
        </ButtonLink>,
      );
      const link = screen.getByRole("link", { name: "Visit" });
      expect(link.tagName).toBe("A");
      expect(link).toHaveAttribute("href", "https://example.com");
    });

    it("renders a plain anchor for mailto URLs", () => {
      renderWithProviders(<ButtonLink to="mailto:test@example.com">Email</ButtonLink>);
      const link = screen.getByRole("link", { name: "Email" });
      expect(link).toHaveAttribute("href", "mailto:test@example.com");
    });

    it("renders a plain anchor for tel URLs", () => {
      renderWithProviders(<ButtonLink to="tel:+1234567890">Call</ButtonLink>);
      const link = screen.getByRole("link", { name: "Call" });
      expect(link).toHaveAttribute("href", "tel:+1234567890");
    });
  });

  describe("internal routes", () => {
    it("renders a router link for relative paths", () => {
      renderWithProviders(<ButtonLink to="/some/internal/route">Internal</ButtonLink>);
      const link = screen.getByRole("link", { name: "Internal" });
      expect(link).toHaveAttribute("href", "/some/internal/route");
    });
  });
});
